function calculatePrice(order: { type: string; base: number }) {
  if (order.type === 'standard') return order.base;
  if (order.type === 'premium') return order.base * 0.9;
  if (order.type === 'enterprise') return order.base * 0.8;
  return order.base;
}

class Invoice {
  total: number;
  customerType: string;
  calculateTotal() {
    if (this.customerType === 'enterprise') return this.total * 0.9;
    if (this.customerType === 'startup') return this.total * 0.95;
    return this.total;
  }
}

// Version A: separate strategy classes
interface PricingStrategy { compute(price: number): number }
class EnterprisePricing implements PricingStrategy { compute(price: number) { return price * 0.9 } }
class Order { constructor(private pricing: PricingStrategy, public price: number) {}
  total() { return this.pricing.compute(this.price) }
}

// Version B: single class with conditional
class OrderV2 {
  constructor(public price: number, public customerType: string) {}
  total() {
    if (this.customerType === 'enterprise') return this.price * 0.9;
    if (this.customerType === 'startup') return this.price * 0.95;
    return this.price;
  }
}
